CREATE TABLE IF NOT EXISTS playbook_topics (
    id VARCHAR(36) PRIMARY KEY,
    numer INT,
    pytanie TEXT,
    odpowiedz_wzorcowa TEXT,
    elementy_kluczowe TEXT,
    elementy_uzupelniajace TEXT,
    odpowiedz_czesciowa TEXT,
    odpowiedz_bledna TEXT,
    przedmiot VARCHAR(255),
    dzial_numer INT,
    dzial_nazwa VARCHAR(255),
    wariant VARCHAR(5),
    numer_pytania INT,
    notatka TEXT,
    id_slug VARCHAR(255),
    stats_json TEXT
);

